using System.Collections.Generic;public class Solution{public IList<int> SpiralOrder(int[][]m){var o=new List<int>();if(m.Length==0)return o;int t=0,b=m.Length-1,l=0,r=m[0].Length-1;while(t<=b&&l<=r){for(int j=l;j<=r;j++)o.Add(m[t][j]);t++;for(int i=t;i<=b;i++)o.Add(m[i][r]);r--;if(t<=b){for(int j=r;j>=l;j--)o.Add(m[b][j]);b--;}if(l<=r){for(int i=b;i>=t;i--)o.Add(m[i][l]);l++;}}return o;}}
